-- Transactional potion application and durable self-use idempotency.
ALTER TABLE dndshare.item_transfer ADD COLUMN application jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE dndshare.item_transfer ADD COLUMN application_result jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE dndshare.item_application (
 char_id bigint NOT NULL REFERENCES dndshare."char"(id) ON DELETE CASCADE,
 client_action_id uuid NOT NULL,
 entry_uid text NOT NULL,
 option_key text NOT NULL DEFAULT '',
 result jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(char_id, client_action_id)
);
UPDATE dndshare.item_type SET fields=fields || '{"key": "consumption", "name": "Применение зелья", "type": "object", "optional": true, "fields": [{"key": "healing", "name": "Восстановление хитов", "type": "text", "hint": "Формула, например 2d4 + 2. Хиты восстанавливаются до максимума."}, {"key": "temporary_hp", "name": "Временные хиты", "type": "text", "hint": "Формула или число. Сохраняется большее значение, временные хиты не складываются."}, {"key": "spell", "name": "Эффект заклинания", "type": "item", "item_type": 5}, {"key": "spell_effect_key", "name": "Вариант эффекта заклинания", "type": "text", "hint": "Ключ связанного эффекта. Пусто — применить все эффекты заклинания."}, {"key": "duration", "name": "Длительность", "type": "object", "fields": [{"key": "kind", "name": "Вид", "type": "select", "default": "manual", "options": [{"label": "До ручного снятия", "value": "manual"}, {"label": "Раунды", "value": "rounds"}, {"label": "Минуты", "value": "minutes"}, {"label": "Часы", "value": "hours"}, {"label": "До отдыха", "value": "until_rest"}, {"label": "Постоянно", "value": "permanent"}]}, {"key": "value", "name": "Значение", "type": "int"}, {"key": "formula", "name": "Случайная длительность", "type": "text", "hint": "Например 1d4. Бросается при применении вместо постоянного значения."}], "optional": true}, {"key": "concentration", "name": "Требует концентрации", "type": "bool"}, {"key": "note", "name": "Что нужно учесть вручную", "type": "text"}, {"key": "choices", "name": "Варианты применения", "type": "object_array", "fields": [{"key": "key", "name": "Ключ варианта", "type": "text"}, {"key": "name", "name": "Название варианта", "type": "text"}, {"key": "status_effects", "name": "Связанные эффекты", "type": "object_array", "fields": [{"key": "key", "name": "Ключ", "type": "text"}, {"key": "effect", "name": "Эффект", "type": "item", "item_type": 15}, {"key": "parameter_bindings", "name": "Параметры", "type": "object_array", "fields": [{"key": "key", "name": "Параметр", "type": "text"}, {"key": "source", "name": "Источник", "type": "select", "options": [{"label": "Текущее значение прогрессии", "value": "scaling_value"}, {"label": "Постоянное значение", "value": "fixed"}]}, {"key": "value", "name": "Значение", "type": "int"}]}, {"key": "concentration", "name": "Концентрация", "type": "bool"}, {"key": "duration", "name": "Длительность", "type": "object", "fields": [{"key": "kind", "name": "Вид", "type": "select", "default": "manual", "options": [{"label": "До ручного снятия", "value": "manual"}, {"label": "Раунды", "value": "rounds"}, {"label": "Минуты", "value": "minutes"}, {"label": "Часы", "value": "hours"}, {"label": "До отдыха", "value": "until_rest"}, {"label": "Постоянно", "value": "permanent"}]}, {"key": "value", "name": "Значение", "type": "int"}, {"key": "formula", "name": "Случайная длительность", "type": "text", "hint": "Например 1d4. Бросается при применении вместо постоянного значения."}]}, {"key": "target", "name": "На кого накладывается", "type": "select", "default": "self", "options": [{"value": "self", "label": "На владельца"}, {"value": "other", "label": "На другое существо"}], "hint": "Эффект на другое существо не включается на листе владельца предмета."}, {"key": "condition", "name": "Условие наложения", "type": "text", "hint": "Укажите попадание, спасбросок и другие условия, которые проверяет игрок."}, {"key": "weapon_damage_key", "name": "Связанный дополнительный урон", "type": "text", "hint": "Переключатель урона этого предмета. Связь поясняет условие, но не накладывает эффект автоматически."}]}]}]}'::jsonb WHERE id=10 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(fields) f WHERE f->>'key'='consumption');
UPDATE dndshare.item_type SET fields=fields || '{"key": "status_effects", "name": "Связанные эффекты", "type": "object_array", "fields": [{"key": "key", "name": "Ключ", "type": "text"}, {"key": "effect", "name": "Эффект", "type": "item", "item_type": 15}, {"key": "parameter_bindings", "name": "Параметры", "type": "object_array", "fields": [{"key": "key", "name": "Параметр", "type": "text"}, {"key": "source", "name": "Источник", "type": "select", "options": [{"label": "Текущее значение прогрессии", "value": "scaling_value"}, {"label": "Постоянное значение", "value": "fixed"}]}, {"key": "value", "name": "Значение", "type": "int"}]}, {"key": "concentration", "name": "Концентрация", "type": "bool"}, {"key": "duration", "name": "Длительность", "type": "object", "fields": [{"key": "kind", "name": "Вид", "type": "select", "default": "manual", "options": [{"label": "До ручного снятия", "value": "manual"}, {"label": "Раунды", "value": "rounds"}, {"label": "Минуты", "value": "minutes"}, {"label": "Часы", "value": "hours"}, {"label": "До отдыха", "value": "until_rest"}, {"label": "Постоянно", "value": "permanent"}]}, {"key": "value", "name": "Значение", "type": "int"}, {"key": "formula", "name": "Случайная длительность", "type": "text", "hint": "Например 1d4. Бросается при применении вместо постоянного значения."}]}, {"key": "target", "name": "На кого накладывается", "type": "select", "default": "self", "options": [{"value": "self", "label": "На владельца"}, {"value": "other", "label": "На другое существо"}], "hint": "Эффект на другое существо не включается на листе владельца предмета."}, {"key": "condition", "name": "Условие наложения", "type": "text", "hint": "Укажите попадание, спасбросок и другие условия, которые проверяет игрок."}, {"key": "weapon_damage_key", "name": "Связанный дополнительный урон", "type": "text", "hint": "Переключатель урона этого предмета. Связь поясняет условие, но не накладывает эффект автоматически."}]}'::jsonb WHERE id=10 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(fields) f WHERE f->>'key'='status_effects');
UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='derived_effects' THEN '{"key": "derived_effects", "name": "Производные эффекты", "type": "object_array", "fields": [{"key": "kind", "name": "Вид", "type": "select", "options": [{"label": "Бонус КД", "value": "armor_bonus"}, {"label": "Бонус скорости", "value": "speed_bonus"}, {"label": "Бонус проверки", "value": "check_bonus"}, {"label": "Бонус навыка", "value": "skill_bonus"}, {"label": "Бонус спасброска", "value": "save_bonus"}, {"label": "Бонус атаки оружием", "value": "weapon_attack_bonus"}, {"label": "Бонус урона оружием", "value": "weapon_damage_bonus"}, {"label": "Режим броска", "value": "roll_mode"}, {"label": "Запрет действия", "value": "activity_block"}, {"value": "roll_bonus", "label": "Кости к броску"}, {"value": "speed_multiplier", "label": "Множитель скорости"}, {"value": "ability_minimum", "label": "Минимальное значение характеристики"}]}, {"key": "value", "name": "Значение", "type": "int"}, {"key": "value_parameter", "name": "Параметр значения", "type": "text"}, {"key": "ability_ids", "name": "Характеристики", "type": "suggest_array", "suggest_id": 16}, {"key": "weapon_kind", "name": "Вид оружия", "type": "select", "options": [{"label": "Любое", "value": "any"}, {"label": "Рукопашное", "value": "melee"}, {"label": "Дальнобойное", "value": "ranged"}]}, {"key": "scopes", "name": "Области броска", "type": "text_array"}, {"key": "mode", "name": "Режим", "type": "select", "options": [{"label": "Преимущество", "value": "advantage"}, {"label": "Помеха", "value": "disadvantage"}]}, {"key": "label", "name": "Пояснение", "type": "text"}, {"key": "ability_modifier", "name": "Характеристика-модификатор", "type": "suggest", "suggest_id": 16}, {"key": "minimum", "name": "Минимальный бонус", "type": "int"}, {"key": "target_parameter", "name": "Параметр цели", "type": "text"}, {"key": "formula", "name": "Формула прибавки", "type": "text", "hint": "Например 1d4. Для костей к броскам атаки и спасброскам."}]}'::jsonb ELSE f END ORDER BY n) FROM jsonb_array_elements(fields) WITH ORDINALITY e(f,n)) WHERE id=15;
UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='effect_source' THEN '{"key": "effect_source", "name": "Источник эффекта", "type": "select", "readonly": true, "filter": true, "options": [{"value": "basic", "label": "Базовые эффекты"}, {"value": "magic_item", "label": "Магические предметы"}, {"value": "spell", "label": "Заклинания"}, {"value": "potion", "label": "Зелья"}]}'::jsonb ELSE f END ORDER BY n) FROM jsonb_array_elements(fields) WITH ORDINALITY e(f,n)) WHERE id=15;
